mapper.select:
SELECT *
FROM lunaerp_business_sales_return_item
WHERE return_id = #{returnId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_business_sales_return_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE return_id = #{returnId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_business_sales_return_item
WHERE return_id = #{returnId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
